using EventSourcedAccount;using Xunit;public sealed class EventSourcingTests{[Fact]public void Replay_rebuilds_state(){var id=Guid.NewGuid();var a=Account.Rehydrate([new AccountOpened(id,"Ada"),new MoneyDeposited(100m),new MoneyWithdrawn(25m)]);Assert.Equal(75m,a.Balance);Assert.Equal(2,a.Version);}[Fact]public void Invalid_withdrawal_emits_no_event(){var a=Account.Open(Guid.NewGuid(),"Ada");var count=a.Changes.Count;Assert.Throws<InvalidOperationException>(()=>a.Withdraw(1m));Assert.Equal(count,a.Changes.Count);}[Fact]public void Append_checks_expected_version(){var s=new EventStore();var id=Guid.NewGuid();s.Append(id,-1,[new AccountOpened(id,"Ada")]);Assert.Throws<ConcurrencyException>(()=>s.Append(id,-1,[new MoneyDeposited(1m)]));}[Fact]public void Uncommitted_changes_are_cleared_after_commit(){var a=Account.Open(Guid.NewGuid(),"Ada");a.MarkCommitted();Assert.Empty(a.Changes);Assert.Equal(0,a.Version);}}
